"""校园 Agent Host + MCP Client 联调示例。

在 campus-mcp 目录运行：
    uv run python agent_host.py --check
    uv run python agent_host.py "查询A栋空余自习室，并介绍预约规则"
    uv run python agent_host.py "查询B栋自习室，并安排学习计划" --subject Python

Host 负责用户输入、模型和工具调用循环；Client 负责通过 MCP 与 Server 通信。
模型配置复用 ck-agents 根目录 .env 中的 LLM_API_KEY、LLM_BASE_URL、LLM_MODEL_ID。
"""

import argparse
import asyncio
import json
import os
import sys
from pathlib import Path

from dotenv import load_dotenv
from mcp import Client, StdioServerParameters
from mcp.shared.exceptions import MCPError
from openai import AsyncOpenAI

APP_DIR = Path(__file__).resolve().parent


def text_content(blocks) -> str:
    """提取本示例的工具、资源及 Prompt 内容中的文本块。"""
    return "\n".join(block.text for block in blocks if hasattr(block, "text"))


async def check_connection(client: Client) -> None:
    """通过真实 MCP 请求验证工具、资源和 Prompt，无需模型 API Key。"""
    tools = await client.list_tools()
    resources = await client.list_resources()
    prompts = await client.list_prompts()
    print("Tools:", [tool.name for tool in tools.tools])
    print("Resources:", [str(resource.uri) for resource in resources.resources])
    print("Prompts:", [prompt.name for prompt in prompts.prompts])

    result = await client.call_tool("search_available_rooms", {"building": "A"})
    rules = await client.read_resource("campus://library/rules")
    plan = await client.get_prompt("study_plan", {"subject": "Python"})
    rooms_text = text_content(result.content)
    rules_text = text_content(rules.contents)
    plan_text = "\n".join(text_content([message.content]) for message in plan.messages)
    if result.is_error or "A101" not in rooms_text:
        raise RuntimeError(f"工具联调失败：{rooms_text}")
    if "08:00" not in rules_text or "Python" not in plan_text:
        raise RuntimeError("资源或 Prompt 返回内容不符合预期")
    print(f"\n工具结果：{rooms_text}\n资源内容：{rules_text}\nPrompt：{plan_text}")
    print("\nMCP 联调通过。")


async def run_agent(client: Client, query: str, subject: str | None = None) -> str:
    """Host 将 MCP 能力交给模型，并通过 Client 执行模型提出的工具调用。"""
    load_dotenv(APP_DIR.parents[2] / ".env")
    for name in ("LLM_API_KEY", "LLM_BASE_URL", "LLM_MODEL_ID"):
        if not os.getenv(name, "").strip():
            raise ValueError(f"请在 ck-agents 根目录 .env 中配置 {name}")

    discovered = await client.list_tools()
    tool_names = {tool.name for tool in discovered.tools}
    # MCP 的工具描述转换成 OpenAI 兼容接口的 Function Calling 描述。
    tools = [
        {
            "type": "function",
            "function": {
                "name": tool.name,
                "description": tool.description or "",
                "parameters": tool.input_schema,
            },
        }
        for tool in discovered.tools
    ]
    print("[Client] 已发现工具：", ", ".join(sorted(tool_names)))

    # Resource 由 Host 主动读取并放入上下文，不需要模型发起工具调用。
    rules = await client.read_resource("campus://library/rules")
    messages = [
        {
            "role": "system",
            "content": (
                "你是校园学习助手，用中文回答。查询空余自习室时必须调用工具，"
                "不得编造房间或声称已完成预约。工具失败时如实说明。\n"
                "以下是 MCP Resource 提供的图书馆规则：\n"
                + text_content(rules.contents)
            ),
        }
    ]
    print("[Client] 已读取图书馆规则。")

    # Prompt 是服务端提供的模板，由用户通过 --subject 选择使用。
    if subject:
        prompt = await client.get_prompt("study_plan", {"subject": subject})
        messages.extend(
            {"role": message.role, "content": text_content([message.content])}
            for message in prompt.messages
        )
        print(f"[Client] 已获取 {subject} 学习规划 Prompt。")
    messages.append({"role": "user", "content": query})

    async with AsyncOpenAI(
        api_key=os.environ["LLM_API_KEY"],
        base_url=os.environ["LLM_BASE_URL"],
        timeout=60,
        max_retries=0,
    ) as llm:
        # 与项目已有 Function Calling 示例一样，限制模型轮数，避免无限调用。
        for step in range(6):
            response = await llm.chat.completions.create(
                model=os.environ["LLM_MODEL_ID"], messages=messages, tools=tools
            )
            message = response.choices[0].message
            messages.append(
                message.model_dump(include={"role", "content", "tool_calls"}, exclude_none=True)
            )
            if not message.tool_calls:
                return message.content or "模型未返回正文。"

            for call in message.tool_calls:
                print(f"[Host 第{step + 1}轮] 调用 {call.function.name}({call.function.arguments})")
                try:
                    arguments = json.loads(call.function.arguments)
                    if call.function.name not in tool_names or not isinstance(arguments, dict):
                        raise ValueError("工具名未注册或参数不是 JSON 对象")
                    # 真正执行的是 MCP RPC，不在 Host 中导入服务端的业务函数。
                    result = await client.call_tool(call.function.name, arguments)
                    output = text_content(result.content)
                    if result.is_error:
                        output = f"工具执行失败：{output}"
                except (ValueError, MCPError) as exc:
                    output = f"工具调用失败：{exc}"
                print(f"[Client] {output}")
                messages.append(
                    {"role": "tool", "tool_call_id": call.id, "content": output}
                )
    raise RuntimeError("已达到最大模型调用轮数，任务尚未完成")


async def main(args: argparse.Namespace) -> None:
    """用当前 Python 环境启动 stdio Server，退出时自动关闭连接和子进程。"""
    server = StdioServerParameters(
        command=sys.executable,
        args=[str(APP_DIR / "server.py")],
        cwd=str(APP_DIR),
    )
    async with Client(server, read_timeout_seconds=30) as client:
        if args.check:
            await check_connection(client)
        else:
            print("\n答复：", await run_agent(client, args.query, args.subject))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="校园 Agent Host + MCP Client")
    parser.add_argument("query", nargs="?", default="查询A栋空余自习室，并介绍图书馆预约规则")
    parser.add_argument("--subject", help="使用服务端的学习规划 Prompt，例如 Python")
    parser.add_argument("--check", action="store_true", help="仅验证 MCP 通信，不调用模型")
    asyncio.run(main(parser.parse_args()))
